def check_poly(n):
    c = [0] * n
    c[n-1] = 1
    for j in range(n-1, 0, -1):
        # c[j-1] - sum_{i=j}^{n-1} c[i] * comb(i, j) * (-1)^(i-j) = 0
        import math
        s = 0
        for i in range(j, n):
            s += c[i] * math.comb(i, j) * ((-1)**(i-j))
        c[j-1] = s

    # Check j=0 condition: sum_{i=0}^{n-1} c[i] * (-1)^i = 0
    s0 = 0
    for i in range(n):
        s0 += c[i] * ((-1)**i)
    return s0 == 0, c

for n in range(1, 15):
    works, c = check_poly(n)
    if works:
        print(f"n={n} works: {c}")
    else:
        print(f"n={n} fails")

import math

def solve_for_a0(n, max_k):
    def get_S(n, k):
        s = 0
        for j in range(1, k + 1):
            s += (j**(n-1)) * math.factorial(j)
        return s

    R = 0
    M = 1
    for k in range(1, max_k + 1):
        sk = get_S(n, k)
        target = (-sk - R) % math.factorial(k+1)
        # M*x = target mod (k+1)!
        # M is k!, so x = (target // M) % (k+1)
        x = (target // M) % (k+1)
        R = R + M * x
        M = math.factorial(k+1)
    return R

for n in [2, 5, 8, 11]:
    a0 = solve_for_a0(n, 10)
    print(f"n={n}, a0={a0}")

